from typing import List, Optional, Union
from taf.ul.sc.unix_functionality import UnixFunctionality  # type: ignore
from taf.ul.sc.perf.devices.bts.enb import AirScaleEnb
from taf.ul.sc.perf.devices.bts.enb import FzpEnb
from taf.ul.sc.perf.devices.bts.gnb import AirScaleGnb
from taf.ul.sc.perf.devices.ue import RTG


class PerformanceTestLine(object):
    __instance = None

    def __new__(cls, *args, **kwargs):
        if PerformanceTestLine.__instance is None:
            PerformanceTestLine.__instance = super(PerformanceTestLine, cls).__new__(cls)

        return PerformanceTestLine.__instance

    def __init__(self,
                 unix_local: Optional[UnixFunctionality] = None,
                 btss: Optional[List[Union[AirScaleEnb, FzpEnb, AirScaleGnb]]] = None,
                 ue: Optional[RTG] = None,
                 core: Optional[str] = None,         # not supported yet
                 name: Optional[str] = None,
                 tl_type: Optional[str] = None,
                 owner: Optional[str] = None,
                 maintainers: Optional[List[str]] = None
                 ):
        """
        Test Line class for taf.ul.sc.perf purposes.

        :param unix_local: Connection to local device
        :param btss: list of all btss in Test Line
        :param ue: Ue simulator eg RTG
        :param core: Core network
        :param name: Test Line name: eg: 2_7_UTE4G072
        :param tl_type: should be related to CM TL type
        :param owner: Could be email addresses or just Nokia login. eg: tkrol or name.surname@nokia.com
        :param maintainers: list of maintainers. Could be email addresses or just Nokia login.
                            eg: [tkrol, name.surname@nokia.com]
        """
        self.unix_local = unix_local
        if btss is None:
            btss = []
        self.btss = btss
        self.ue = ue
        self.core = core
        self.name = name
        self.tl_type = tl_type
        self.owner = owner
        self.maintainers = maintainers
        # other specific parameters regarding to whole test line. post_server etc
        try:
            self.main_bts = self.btss[0]
        except IndexError:
            pass
        self.small_cell_enbs = self._get_small_cell_enbs()

    def _get_small_cell_enbs(self):
        small_cell_enbs = []
        for bts in self.btss:
            if isinstance(bts, FzpEnb):
                small_cell_enbs.append(bts)

        return small_cell_enbs

    def get_bts(self, name):
        for bts in self.btss:
            if bts.name == name:
                return bts

        raise Exception("BTS {} is not defined".format(name))
